import{_ as e,o as i,c as s,a5 as o}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Empacotamento, assinatura e registros de plugins","description":"","frontmatter":{"title":"Empacotamento, assinatura e registros de plugins","docId":"developer.plugins.packaging-registry","translationKey":"developer.plugins.packaging-registry","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"b5c1b8dc63aafc5216467a00317c6670ac6744235abfc724fe372f3a28427ee8","translationRevision":"88986b5baa400db98038166edb0f3ade2dcdae241d1aa442986e3463bdde8baa","order":280},"headers":[],"relativePath":"pt/developer/plugins/packaging-registry.md","filePath":"pt/developer/plugins/packaging-registry.md","lastUpdated":1794611623000}'),t={name:"pt/developer/plugins/packaging-registry.md"};function r(n,a,d,p,l,c){return i(),s("div",null,[...a[0]||(a[0]=[o(`<h1 id="plugin-packaging-signing-and-registries" tabindex="-1">Empacotamento, assinatura e registros de plugins <a class="header-anchor" href="#plugin-packaging-signing-and-registries" aria-label="Permalink to &quot;Empacotamento, assinatura e registros de plugins {#plugin-packaging-signing-and-registries}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Distribua um pacote cujos bytes, autoridade do publicador e compatibilidade com o host possam ser verificados independentemente. Comece com um plugin validado e um destino compatível. A assinatura precisa de chaves privadas de autor mantidas fora do repositório; delegação da raiz do registro é responsabilidade separada do operador.</p><h2 id="prepare-a-reviewable-archive" tabindex="-1">Prepare um arquivo revisável <a class="header-anchor" href="#prepare-a-reviewable-archive" aria-label="Permalink to &quot;Prepare um arquivo revisável {#prepare-a-reviewable-archive}&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keygen</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --publisher</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> acme</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --out</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys</span></span></code></pre></div><p><code>build</code> compila o pacote e cria arquivos <code>.plugin</code>. Entrada do manifesto, recursos, idiomas, saída da interface e dependências relevantes do runtime são incluídos com <code>checksums.json</code>. Compilações nativas/de processo precisam de um artefato de destino compatível; pacotes apenas JavaScript continuam portáteis até que addons nativos ou funcionalidades da plataforma os restrinjam.</p><p>Para um arquivo já compilado, use caminhos exatos em vez de um curinga não revisado:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sign</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.key.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span></span></code></pre></div><p>Substitua o nome do arquivo pela saída real específica do destino da compilação. A assinatura cobre as somas de verificação, que cobrem os arquivos do pacote. Chaves públicas podem ser compartilhadas; arquivos de chaves privadas não devem entrar no controle de versão nem em registros.</p><h2 id="trust-and-update-policy" tabindex="-1">Política de confiança e atualização <a class="header-anchor" href="#trust-and-update-policy" aria-label="Permalink to &quot;Política de confiança e atualização {#trust-and-update-policy}&quot;">​</a></h2><p>O protocolo de registro estático tem autoridade assinada pela raiz e chaves delegadas de índice/publicador. Aprovação do namespace do publicador não é o mesmo que integridade de pacote, e um resumo do catálogo do Cloud não pode substituir nenhuma das cadeias de assinatura. O resolvedor verifica canal, mecanismo, esquema/protocolo/ABI, runtime e destino. Versões retiradas, revogadas ou incompatíveis continuam inelegíveis mesmo quando o hash do arquivo corresponde.</p><p>A instalação no host apresenta primeiro uma revisão. Atualizações automáticas exigem política permitida, pacote sem versão fixada, publicador assinado compatível e nenhuma nova autoridade; permissões ampliadas exigem revisão. A instalação pelo catálogo Cloud do produto é distinta da autoria de registro estático de baixo nível, e fluxos comuns do produto rejeitam URLs remotas arbitrárias de pacotes.</p><h2 id="expected-result-recovery-and-verification" tabindex="-1">Resultado esperado, recuperação e verificação <a class="header-anchor" href="#expected-result-recovery-and-verification" aria-label="Permalink to &quot;Resultado esperado, recuperação e verificação {#expected-result-recovery-and-verification}&quot;">​</a></h2><p>O instalador pode verificar bytes antes de aplicar um pacote revisado e manter estado de reversão/recuperação. A preparação de desenvolvimento fica fora do gerenciamento do instalador. Em falha de confiança, corrija delegação ou metadados do publicador em vez de usar flags para ignorar assinaturas como política normal de distribuição. Em inicialização incerta do runtime, pare a substituição e reconcilie o resultado mantido.</p><p>Use <code>bun scripts/task.ts rust test -p tiktools-plugin-package --locked</code> e os testes de registro para dados de teste offline. O <a href="https://github.com/nglmercer/TikTools-app/tree/remake/crates/tiktools-plugin-package/src" target="_blank" rel="noreferrer">verificador de pacotes</a> e o <a href="https://github.com/nglmercer/TikTools-app/blob/remake/crates/tiktools-plugin-registry/src/model.rs" target="_blank" rel="noreferrer">modelo de registro</a> definem os formatos técnicos; a infraestrutura de publicação precisa de aceitação separada pelo operador.</p><h2 id="operational-details" tabindex="-1">Detalhes de operação <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Detalhes de operação {#operational-details}&quot;">​</a></h2><p>Interprete o JSON da verificação, não apenas o código de saída. <code>verify</code> pode terminar com sucesso e <code>signature.status</code> igual a <code>unsigned</code> ou <code>untrusted</code>. Aceite somente <code>verified</code> com ID do pacote, editor e chave esperados e confira a política de distribuição. Uma chave local <code>--trust</code> comprova essa assinatura, não delegação do registro ou aprovação do namespace. Checksums isolados não comprovam autoridade nem confiança do updater. A automação abaixo deve falhar diante de resultado inesperado.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tiktools-plugin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verify</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dist-plugin/acme.hello-0.1.0.plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --trust</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /private/path/keys/acme-1.pub.json</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> verification.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;const r = await Bun.file(&quot;verification.json&quot;).json(); if (r.signature?.status !== &quot;verified&quot; || r.id !== &quot;acme.hello&quot; || r.signature.publisher !== &quot;acme&quot; || r.signature.keyId !== &quot;acme-1&quot;) throw new Error(&quot;Package trust did not match policy&quot;);&#39;</span></span></code></pre></div>`,18)])])}const g=e(t,[["render",r]]);export{h as __pageData,g as default};
